async function api(path:string,body?:Any,method?:string):Promise<Any>{
 const form=body instanceof FormData;
 const r=await fetch('/api/v1'+path,{method:method||(body===undefined?'GET':'POST'),headers:body===undefined?{}:{'X-NeuroStudio':csrf,...(form?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:form?body:JSON.stringify(body)});
 const data=localizePayload(await r.json());if(r.status===401&&path!=='/session'){const session=await (await fetch('/api/v1/session')).json();csrf=session.token;return api(path,body,method)}if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data;
}
