 const selectedRun=useRef<string|null>(null),seen=useRef(new Set<string>());
 useEffect(()=>{if(!deleteTarget)return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector<HTMLElement>('[aria-labelledby="delete-project-title"]');const listener=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!dialog?.querySelector<HTMLButtonElement>('.destructive')?.disabled){event.preventDefault();setDeleteTarget(null)}if(event.key==='Tab'){const buttons=Array.from(dialog?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')||[]);const first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}};document.addEventListener('keydown',listener);return()=>{document.removeEventListener('keydown',listener);if(previous?.isConnected)previous.focus()}},[deleteTarget?.id]);
