 function open(r:Any){recordRef.current=r;draftRef.current=clone(r.project);setRecord(r);setDraft(clone(r.project));setDirty(false);undo.current=[];redo.current=[];setProfile(null);setRun(null);selectedRun.current=null;setEvents([]);setLab(0);setPage('studio');setValidation(null);setValidationGeneration(g=>g+1);setTransformPreview(null);setFeatureMaps(null);setExplanation(null)}
