   {(page==='home'||(!draft&&page==='studio'))?<div className="content home"><div className="eyebrow">NEURO STUDIO</div><h1>{txt('Dự án học máy của bạn','Your machine learning projects')}</h1><p className="subtitle">{txt('Khám phá dữ liệu, xây mô hình và nhìn thấy cách máy học - từng bước một.','Explore data, build models, and see machine learning come to life.')}</p><DemoGallery onCreate={create} busy={busy}/><section className="card custom-import"><div><h2>{t("Dùng dữ liệu của bạn")}</h2><p>{t("Tạo dự án từ CSV hoặc bộ ảnh. Dữ liệu được nhập vào workspace và chỉ xử lý trên máy này.")}</p></div><div className="row"><button className="primary" disabled={busy} onClick={()=>{if(importRef.current){importRef.current.accept='.csv';importRef.current.click()}}}><Upload size={16}/>{t("Nhập CSV")}</button><button className="secondary" disabled={busy} onClick={()=>{if(importRef.current){importRef.current.accept='.zip';importRef.current.click()}}}>{t("Nhập ZIP ảnh")}</button><button className="secondary" disabled={busy} onClick={()=>folderRef.current?.click()}><FolderOpen size={16}/>{t("Chọn thư mục ảnh")}</button></div></section><div className="section-head"><h2>{txt('Dự án gần đây','Recent projects')}</h2><button className="secondary" onClick={()=>projectImport.current?.click()}><Upload size={15}/>{t("Nhập project JSON")}</button></div><div className="project-list">{projects.length?projects.map(p=><div className="project-row" key={p.id}><button className="project-open" disabled={busy} onClick={()=>select(p.id)}><span className="project-symbol">{p.project.backend==='torch'?<Layers3/>:<Leaf/>}</span><span><strong>{p.project.name}</strong><small>{p.project.backend==='torch'?t('PyTorch · Phân loại ảnh'):p.project.task==='regression'?t('scikit-learn · Hồi quy'):t('scikit-learn · Phân loại bảng')}</small></span><span className="project-date">{new Date(p.updated*1000).toLocaleDateString(document.documentElement.lang==='vi'?'vi-VN':'en-US')}</span><ArrowRight size={18}/></button><button className="icon-btn danger project-delete" aria-label={t('Xóa dự án ')+p.project.name} onClick={()=>setDeleteTarget(p)}><Trash2 size={17}/></button></div>):<div className="empty">{t("Chọn một template ở trên để bắt đầu. Mọi thay đổi đều được lưu trên máy của bạn.")}</div>}</div></div>:null}
   {page==='home'&&<div className="content"><SplitImport onSubmit={async(data,image,task)=>{await act(async()=>{const id=await importProject(image);edit(p=>{p.data.target=String(data.get('target')||'target')});if(task==='regression')edit(p=>{p.task='regression';p.data.stratify=false;p.graphs.find((g:Any)=>g.kind==='model').nodes=[clone(templates.regression.graphs.find((g:Any)=>g.kind==='model').nodes[0])];p.training.metrics=[];p.training.primary_metric=null});const job=await api('/datasets/import-splits',data);pendingImports.current[job.id]=id;setNotice(t('Đang nhập và kiểm tra dữ liệu…'));setJobs(j=>[job,...j])})}}/></div>}
